-- ------------------------------------------------------------------------
-- 0010_student_metadata.sql
-- ------------------------------------------------------------------------

-- The only column 0008 does not already declare on crm.students.
-- Everything else the CRM port needed (father_name, guardian_*, mode,
-- department_id, sub_section_id, session_id, incentive_amount) is in 0008;
-- `referred_by_associate` arrives with the associates table in 0016.
alter table crm.students
  add column if not exists metadata jsonb not null default '{}'::jsonb;

create index if not exists crm_students_metadata_idx
  on crm.students using gin (metadata);

-- ------------------------------------------------------------------------
-- 0011_student_documents_exams.sql
-- ------------------------------------------------------------------------

-- Student documents (10th marksheet, passport, visa, etc.)
create table if not exists crm.student_documents (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references crm.students(id) on delete cascade,
  doc_type text not null check (doc_type in (
    '10th_marksheet','12th_marksheet','graduation','passport',
    'sop','lor','ielts_scorecard','pte_scorecard','offer_letter','visa','other'
  )),
  status text not null default 'pending' check (status in ('pending','received','verified','rejected')),
  file_url text,
  notes text,
  expiry_date date,
  uploaded_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (student_id, doc_type)
);

create index if not exists crm_student_documents_student_idx on crm.student_documents (student_id);

-- Student exams (IELTS, PTE, etc.)
create table if not exists crm.student_exams (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references crm.students(id) on delete cascade,
  exam_type text not null check (exam_type in (
    'ielts','pte','toefl','practical','final_exam','mock_test','other'
  )),
  exam_name text not null,
  exam_date date,
  centre text,
  hall_ticket_number text,
  admit_card_url text,
  score text,
  is_passed boolean,
  remarks text,
  created_at timestamptz not null default now()
);

create index if not exists crm_student_exams_student_idx on crm.student_exams (student_id);

-- RLS. Both tables carry a student's identity documents and exam results, so
-- they follow crm.students: managers see everything, the assigned counsellor
-- or mentor sees their own, and the student sees their own via the portal.
alter table crm.student_documents enable row level security;
alter table crm.student_exams enable row level security;

drop policy if exists "manager reads documents" on crm.student_documents;
create policy "manager reads documents" on crm.student_documents for select to authenticated
  using (crm.is_manager());
drop policy if exists "own student documents" on crm.student_documents;
create policy "own student documents" on crm.student_documents for select to authenticated
  using (exists (
    select 1 from crm.students s
     where s.id = student_id
       and (s.assigned_counsellor = auth.uid() or s.mentor_telecaller_id = auth.uid())
  ));
drop policy if exists "staff write documents" on crm.student_documents;
create policy "staff write documents" on crm.student_documents for all to authenticated
  using (crm.is_manager()) with check (crm.is_crm_staff());

drop policy if exists "manager reads exams" on crm.student_exams;
create policy "manager reads exams" on crm.student_exams for select to authenticated
  using (crm.is_manager());
drop policy if exists "own student exams" on crm.student_exams;
create policy "own student exams" on crm.student_exams for select to authenticated
  using (exists (
    select 1 from crm.students s
     where s.id = student_id
       and (s.assigned_counsellor = auth.uid() or s.mentor_telecaller_id = auth.uid())
  ));
drop policy if exists "staff write exams" on crm.student_exams;
create policy "staff write exams" on crm.student_exams for all to authenticated
  using (crm.is_manager()) with check (crm.is_crm_staff());

-- ------------------------------------------------------------------------
-- 0012_appointments.sql
-- ------------------------------------------------------------------------

-- Appointments: counselor/admin bookings against a lead (office visit or Google Meet).

create table if not exists crm.appointments (
  id               uuid primary key default gen_random_uuid(),
  lead_id           uuid not null references crm.leads(id) on delete cascade,
  appointment_type  text not null check (appointment_type in ('office_visit', 'google_meet')),
  meet_link         text,
  host_id           uuid not null references public.profiles(id) on delete set null,
  created_by        uuid not null references public.profiles(id) on delete set null,
  scheduled_date    date not null,
  scheduled_time    time not null,
  duration_minutes  int not null default 30 check (duration_minutes > 0),
  status            text not null default 'scheduled'
                     check (status in ('scheduled', 'completed', 'cancelled', 'no_show')),
  notes             text,
  review_note       text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint appointments_meet_link_required check (
    appointment_type <> 'google_meet' or (meet_link is not null and btrim(meet_link) <> '')
  )
);

create index if not exists crm_appointments_lead_idx      on crm.appointments (lead_id);
create index if not exists crm_appointments_date_idx       on crm.appointments (scheduled_date);
create index if not exists crm_appointments_host_idx       on crm.appointments (host_id);

-- Slot lock: no two active bookings for the same host at the same slot.
create unique index if not exists crm_appointments_slot_unique
  on crm.appointments (host_id, scheduled_date, scheduled_time)
  where status <> 'cancelled';

create or replace function crm.set_appointments_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end;
$$;

drop trigger if exists crm_appointments_updated_at on crm.appointments;
create trigger crm_appointments_updated_at
  before update on crm.appointments
  for each row execute function crm.set_appointments_updated_at();

alter table crm.appointments enable row level security;

drop policy if exists "staff read appointments" on crm.appointments;
create policy "staff read appointments" on crm.appointments for select to authenticated
  using (crm.is_crm_staff());

drop policy if exists "staff insert appointments" on crm.appointments;
create policy "staff insert appointments" on crm.appointments for insert to authenticated
  with check (
    crm.is_crm_staff()
    and created_by = auth.uid()
    -- The host must be an active staff member. Any staff member can host;
    -- the enum has no separate "can be booked" role to narrow it to.
    and exists (select 1 from public.profiles where id = host_id and is_active)
  );

drop policy if exists "own appointments update" on crm.appointments;
create policy "own appointments update" on crm.appointments for update to authenticated
  using (
    host_id = auth.uid() or created_by = auth.uid() or crm.is_manager()
  )
  with check (
    host_id = auth.uid() or created_by = auth.uid() or crm.is_manager()
  );

drop policy if exists "manager delete appointments" on crm.appointments;
create policy "manager delete appointments" on crm.appointments for delete to authenticated
  using (crm.is_manager());

-- ------------------------------------------------------------------------
-- 0013_lead_capture_forms.sql
-- ------------------------------------------------------------------------

-- Lead capture forms: public-facing Meta/Facebook ad landing pages.

create table if not exists crm.lead_capture_forms (
  id                uuid primary key default gen_random_uuid(),
  slug              text unique not null,
  title             text not null,
  subtitle          text,
  fields            jsonb not null default '[]'::jsonb,
  success_message   text default 'Thank you! Our team will contact you shortly.',
  source            text not null default 'meta_ads',
  is_active         boolean not null default true,
  submissions_count integer not null default 0,
  created_by        uuid references public.profiles(id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists lead_capture_forms_slug_idx on crm.lead_capture_forms (slug);

alter table crm.lead_capture_forms enable row level security;

drop policy if exists "public read active forms" on crm.lead_capture_forms;
create policy "public read active forms" on crm.lead_capture_forms for select
  using (is_active = true);

drop policy if exists "admin manage forms" on crm.lead_capture_forms;
create policy "admin manage forms" on crm.lead_capture_forms for all
  using (crm.is_manager())
  with check (crm.is_manager());

create or replace function public.set_lcf_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end;
$$;

drop trigger if exists lcf_updated_at on crm.lead_capture_forms;
create trigger lcf_updated_at
  before update on crm.lead_capture_forms
  for each row execute function public.set_lcf_updated_at();

-- ------------------------------------------------------------------------
-- 0014_notifications.sql
-- ------------------------------------------------------------------------

-- Notifications: admin broadcasts and targeted messages.
-- dcwcrm keeps these in public because non-CRM staff also need to read them.

create table if not exists crm.notifications (
  id          uuid primary key default gen_random_uuid(),
  title       text not null,
  message     text not null,
  type        text not null default 'info'
              check (type in ('info', 'warning', 'success', 'alert')),
  target_role text,
  target_user_id uuid references public.profiles(id) on delete cascade,
  created_by  uuid references public.profiles(id) on delete set null,
  created_at  timestamptz not null default now()
);

create table if not exists crm.notification_reads (
  id              uuid primary key default gen_random_uuid(),
  notification_id uuid not null references crm.notifications(id) on delete cascade,
  user_id         uuid not null references public.profiles(id) on delete cascade,
  read_at         timestamptz default now(),
  unique (notification_id, user_id)
);

create index if not exists idx_notifications_target_user on crm.notifications (target_user_id);
create index if not exists idx_notifications_target_role on crm.notifications (target_role);
create index if not exists idx_notifications_created on crm.notifications (created_at desc);

alter table crm.notifications enable row level security;
alter table crm.notification_reads enable row level security;

drop policy if exists "authenticated read notifications" on crm.notifications;
create policy "authenticated read notifications" on crm.notifications for select
  using (auth.uid() is not null);

drop policy if exists "admin insert notifications" on crm.notifications;
create policy "admin insert notifications" on crm.notifications for insert
  with check (
    crm.is_manager()
  );

drop policy if exists "own notification reads" on crm.notification_reads;
create policy "own notification reads" on crm.notification_reads for select
  using (auth.uid() = user_id);

drop policy if exists "own notification read insert" on crm.notification_reads;
create policy "own notification read insert" on crm.notification_reads for insert
  with check (auth.uid() = user_id);

-- ------------------------------------------------------------------------
-- 0015_student_portal.sql
-- ------------------------------------------------------------------------

-- Student portal columns on crm.students
ALTER TABLE crm.students
  ADD COLUMN IF NOT EXISTS portal_user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS portal_username text,
  ADD COLUMN IF NOT EXISTS portal_temp_password text,
  ADD COLUMN IF NOT EXISTS portal_active boolean not null default false,
  ADD COLUMN IF NOT EXISTS university_name text,
  ADD COLUMN IF NOT EXISTS board_name text,
  ADD COLUMN IF NOT EXISTS father_name text,
  ADD COLUMN IF NOT EXISTS guardian_name text,
  ADD COLUMN IF NOT EXISTS guardian_phone text,
  ADD COLUMN IF NOT EXISTS guardian_relationship text,
  ADD COLUMN IF NOT EXISTS dob date,
  ADD COLUMN IF NOT EXISTS gender text CHECK (gender IN ('male','female','other')),
  ADD COLUMN IF NOT EXISTS address text,
  ADD COLUMN IF NOT EXISTS state text,
  ADD COLUMN IF NOT EXISTS pincode text,
  ADD COLUMN IF NOT EXISTS verification_status text NOT NULL DEFAULT 'pending'
    CHECK (verification_status IN ('pending','in_review','verified','rejected')),
  ADD COLUMN IF NOT EXISTS exam_status text NOT NULL DEFAULT 'not_scheduled'
    CHECK (exam_status IN ('not_scheduled','scheduled','completed','result_awaited','passed','failed')),
  ADD COLUMN IF NOT EXISTS result_status text NOT NULL DEFAULT 'awaited'
    CHECK (result_status IN ('awaited','declared','passed','failed','re_appear')),
  ADD COLUMN IF NOT EXISTS admit_card_url text,
  ADD COLUMN IF NOT EXISTS enrollment_card_url text,
  ADD COLUMN IF NOT EXISTS id_card_url text,
  ADD COLUMN IF NOT EXISTS marksheet_url text,
  ADD COLUMN IF NOT EXISTS certificate_url text,
  ADD COLUMN IF NOT EXISTS profile_photo_url text,
  ADD COLUMN IF NOT EXISTS admission_progress int NOT NULL DEFAULT 0 CHECK (admission_progress BETWEEN 0 AND 100);

CREATE UNIQUE INDEX IF NOT EXISTS crm_students_portal_user_idx ON crm.students(portal_user_id) WHERE portal_user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS crm_students_portal_active_idx ON crm.students(portal_active);

-- Student notifications
CREATE TABLE IF NOT EXISTS crm.student_notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id uuid REFERENCES crm.students(id) ON DELETE CASCADE,
  title text NOT NULL,
  message text NOT NULL,
  type text NOT NULL DEFAULT 'info' CHECK (type IN ('info','success','warning','alert')),
  file_url text,
  category text,
  is_read boolean NOT NULL DEFAULT false,
  created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS crm_student_notif_student_idx ON crm.student_notifications(student_id);
CREATE INDEX IF NOT EXISTS crm_student_notif_read_idx ON crm.student_notifications(student_id, is_read);

-- Student announcements
CREATE TABLE IF NOT EXISTS crm.student_announcements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  body text NOT NULL,
  type text NOT NULL DEFAULT 'general' CHECK (type IN ('general','exam','result','fee','urgent')),
  is_active boolean NOT NULL DEFAULT true,
  created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz
);
CREATE INDEX IF NOT EXISTS crm_announcements_active_idx ON crm.student_announcements(is_active, created_at DESC);

-- Student support tickets
CREATE TABLE IF NOT EXISTS crm.student_support_tickets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id uuid NOT NULL REFERENCES crm.students(id) ON DELETE CASCADE,
  subject text NOT NULL,
  message text NOT NULL,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','resolved','closed')),
  priority text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','urgent')),
  admin_reply text,
  replied_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  replied_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS crm_tickets_student_idx ON crm.student_support_tickets(student_id);
CREATE INDEX IF NOT EXISTS crm_tickets_status_idx ON crm.student_support_tickets(status);

-- Study materials
CREATE TABLE IF NOT EXISTS crm.study_materials (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  description text,
  type text NOT NULL DEFAULT 'pdf' CHECK (type IN ('ebook','pdf_notes','syllabus','recorded_class','live_class','other')),
  url text,
  course_id uuid REFERENCES crm.courses(id) ON DELETE SET NULL,
  sub_course_id uuid REFERENCES crm.sub_courses(id) ON DELETE SET NULL,
  is_active boolean NOT NULL DEFAULT true,
  uploaded_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS crm_materials_course_idx ON crm.study_materials(course_id, is_active);
CREATE INDEX IF NOT EXISTS crm_materials_type_idx ON crm.study_materials(type, is_active);

-- Student FAQs
CREATE TABLE IF NOT EXISTS crm.student_faqs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question text NOT NULL,
  answer text NOT NULL,
  category text NOT NULL DEFAULT 'general',
  sort_order int NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- RLS
ALTER TABLE crm.student_notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm.student_announcements ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm.student_support_tickets ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm.study_materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm.student_faqs ENABLE ROW LEVEL SECURITY;

-- Admin/backend: full access
drop policy if exists "admin_student_notif" on crm.student_notifications;
CREATE POLICY "admin_student_notif" ON crm.student_notifications FOR ALL
  USING (crm.is_manager());
drop policy if exists "admin_announcements" on crm.student_announcements;
CREATE POLICY "admin_announcements" ON crm.student_announcements FOR ALL
  USING (crm.is_manager());
drop policy if exists "admin_tickets" on crm.student_support_tickets;
CREATE POLICY "admin_tickets" ON crm.student_support_tickets FOR ALL
  USING (crm.is_manager());
drop policy if exists "admin_materials" on crm.study_materials;
CREATE POLICY "admin_materials" ON crm.study_materials FOR ALL
  USING (crm.is_manager());
drop policy if exists "admin_faqs" on crm.student_faqs;
CREATE POLICY "admin_faqs" ON crm.student_faqs FOR ALL
  USING (crm.is_manager());

-- Students: own notifications (read + mark read)
drop policy if exists "student_own_notif" on crm.student_notifications;
CREATE POLICY "student_own_notif" ON crm.student_notifications FOR SELECT
  USING (student_id IN (SELECT id FROM crm.students WHERE portal_user_id = auth.uid()));
drop policy if exists "student_mark_notif_read" on crm.student_notifications;
CREATE POLICY "student_mark_notif_read" ON crm.student_notifications FOR UPDATE
  USING (student_id IN (SELECT id FROM crm.students WHERE portal_user_id = auth.uid()));

-- Students: announcements
drop policy if exists "student_view_announcements" on crm.student_announcements;
CREATE POLICY "student_view_announcements" ON crm.student_announcements FOR SELECT
  USING (is_active = true AND (expires_at IS NULL OR expires_at > now()));

-- Students: own tickets
drop policy if exists "student_own_tickets" on crm.student_support_tickets;
CREATE POLICY "student_own_tickets" ON crm.student_support_tickets FOR SELECT
  USING (student_id IN (SELECT id FROM crm.students WHERE portal_user_id = auth.uid()));
drop policy if exists "student_create_tickets" on crm.student_support_tickets;
CREATE POLICY "student_create_tickets" ON crm.student_support_tickets FOR INSERT
  WITH CHECK (student_id IN (SELECT id FROM crm.students WHERE portal_user_id = auth.uid()));

-- Students: active materials for their course
drop policy if exists "student_view_materials" on crm.study_materials;
CREATE POLICY "student_view_materials" ON crm.study_materials FOR SELECT
  USING (
    is_active = true AND (
      course_id IS NULL
      OR course_id IN (SELECT course_id FROM crm.students WHERE portal_user_id = auth.uid() AND course_id IS NOT NULL)
    )
  );

-- Students: FAQs
drop policy if exists "student_view_faqs" on crm.student_faqs;
CREATE POLICY "student_view_faqs" ON crm.student_faqs FOR SELECT
  USING (is_active = true);

-- Students: own student record
drop policy if exists "student_read_own" on crm.students;
CREATE POLICY "student_read_own" ON crm.students FOR SELECT
  USING (portal_user_id = auth.uid());
drop policy if exists "student_update_own_profile" on crm.students;
CREATE POLICY "student_update_own_profile" ON crm.students FOR UPDATE
  USING (portal_user_id = auth.uid())
  WITH CHECK (portal_user_id = auth.uid());

-- Students: own payments
drop policy if exists "student_own_payments" on crm.payments;
CREATE POLICY "student_own_payments" ON crm.payments FOR SELECT
  USING (student_id IN (SELECT id FROM crm.students WHERE portal_user_id = auth.uid()));

