-- ------------------------------------------------------------------------
-- 0016_associates_portal.sql
-- ------------------------------------------------------------------------

-- Associates portal: referral partners who bring in students/leads.

create table if not exists crm.associates (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone text not null,
  father_phone text,
  email text not null unique,
  aadhar_number text,
  pan_number text,
  current_address text,
  current_city text,
  current_state text,
  current_pincode text,
  permanent_address text,
  permanent_city text,
  permanent_state text,
  permanent_pincode text,
  same_as_current boolean not null default false,
  bank_name text,
  account_number text,
  ifsc_code text,
  account_holder_name text,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  associate_code text unique,
  user_id uuid references public.profiles(id) on delete set null,
  wallet_balance numeric not null default 0,
  rejection_reason text,
  coordinator_id uuid references public.profiles(id) on delete set null,
  coordinator_name text,
  temp_password text,
  aadhar_doc_url text,
  pan_doc_url text,
  cheque_doc_url text,
  state text,
  district text,
  city text,
  institution_name text,
  institution_address text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  approved_at timestamptz,
  approved_by uuid references public.profiles(id) on delete set null
);

create table if not exists crm.associate_wallet_txns (
  id uuid primary key default gen_random_uuid(),
  associate_id uuid not null references crm.associates(id) on delete cascade,
  type text not null check (type in ('credit', 'debit')),
  amount numeric not null,
  reason text,
  created_at timestamptz not null default now()
);

create table if not exists crm.associate_notifications (
  id uuid primary key default gen_random_uuid(),
  associate_id uuid references crm.associates(id) on delete cascade,
  title text not null,
  message text,
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists crm.associate_dispatches (
  id uuid primary key default gen_random_uuid(),
  associate_id uuid not null references crm.associates(id) on delete cascade,
  item_name text not null,
  quantity int not null default 1,
  tracking_number text,
  status text not null default 'processing' check (status in ('processing', 'shipped', 'delivered')),
  dispatched_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists crm.wallet_recharge_requests (
  id uuid primary key default gen_random_uuid(),
  associate_id uuid not null references crm.associates(id) on delete cascade,
  amount numeric not null,
  receipt_url text,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  rejection_reason text,
  approved_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  approved_at timestamptz
);

create table if not exists crm.associate_resources (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text,
  type text not null default 'other'
    check (type in ('brochure','fee_structure','admission_form','marketing','poster','reel','training','other')),
  url text not null,
  file_size text,
  is_active boolean not null default true,
  uploaded_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create table if not exists crm.associate_support_tickets (
  id uuid primary key default gen_random_uuid(),
  associate_id uuid not null references crm.associates(id) on delete cascade,
  subject text not null,
  message text not null,
  status text not null default 'open'
    check (status in ('open','in_progress','resolved','closed')),
  priority text not null default 'normal'
    check (priority in ('low','normal','high','urgent')),
  admin_reply text,
  replied_by uuid references public.profiles(id) on delete set null,
  replied_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists crm_associates_user_idx on crm.associates(user_id) where user_id is not null;
create index if not exists crm_associates_status_idx on crm.associates(status);
create index if not exists crm_assoc_wallet_assoc_idx on crm.associate_wallet_txns(associate_id);
create index if not exists crm_assoc_notif_assoc_idx on crm.associate_notifications(associate_id);
create index if not exists crm_assoc_dispatch_assoc_idx on crm.associate_dispatches(associate_id);
create index if not exists crm_assoc_resources_type_idx on crm.associate_resources(type, is_active);
create index if not exists crm_assoc_tickets_assoc_idx on crm.associate_support_tickets(associate_id);
create index if not exists crm_assoc_tickets_status_idx on crm.associate_support_tickets(status);
create index if not exists crm_recharge_assoc_idx on crm.wallet_recharge_requests(associate_id);

alter table crm.associates enable row level security;
alter table crm.associate_wallet_txns enable row level security;
alter table crm.associate_notifications enable row level security;
alter table crm.associate_dispatches enable row level security;
alter table crm.wallet_recharge_requests enable row level security;
alter table crm.associate_resources enable row level security;
alter table crm.associate_support_tickets enable row level security;

-- Associates read own, admin manages all
drop policy if exists "admin_associates_all" on crm.associates;
CREATE POLICY "admin_associates_all" ON crm.associates FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());
drop policy if exists "associate_read_own" on crm.associates;
CREATE POLICY "associate_read_own" ON crm.associates FOR SELECT
  USING (user_id = auth.uid());
drop policy if exists "associate_update_own" on crm.associates;
CREATE POLICY "associate_update_own" ON crm.associates FOR UPDATE
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

drop policy if exists "admin_wallet_all" on crm.associate_wallet_txns;
CREATE POLICY "admin_wallet_all" ON crm.associate_wallet_txns FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());
drop policy if exists "associate_read_wallet" on crm.associate_wallet_txns;
CREATE POLICY "associate_read_wallet" ON crm.associate_wallet_txns FOR SELECT
  USING (associate_id IN (SELECT id FROM crm.associates WHERE user_id = auth.uid()));

drop policy if exists "admin_notif_all" on crm.associate_notifications;
CREATE POLICY "admin_notif_all" ON crm.associate_notifications FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());
drop policy if exists "associate_read_notif" on crm.associate_notifications;
CREATE POLICY "associate_read_notif" ON crm.associate_notifications FOR SELECT
  USING (associate_id IN (SELECT id FROM crm.associates WHERE user_id = auth.uid()));
drop policy if exists "associate_mark_notif" on crm.associate_notifications;
CREATE POLICY "associate_mark_notif" ON crm.associate_notifications FOR UPDATE
  USING (associate_id IN (SELECT id FROM crm.associates WHERE user_id = auth.uid()));

drop policy if exists "admin_dispatch_all" on crm.associate_dispatches;
CREATE POLICY "admin_dispatch_all" ON crm.associate_dispatches FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());
drop policy if exists "associate_read_dispatch" on crm.associate_dispatches;
CREATE POLICY "associate_read_dispatch" ON crm.associate_dispatches FOR SELECT
  USING (associate_id IN (SELECT id FROM crm.associates WHERE user_id = auth.uid()));

drop policy if exists "admin_recharge_all" on crm.wallet_recharge_requests;
CREATE POLICY "admin_recharge_all" ON crm.wallet_recharge_requests FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());
drop policy if exists "associate_read_recharge" on crm.wallet_recharge_requests;
CREATE POLICY "associate_read_recharge" ON crm.wallet_recharge_requests FOR SELECT
  USING (associate_id IN (SELECT id FROM crm.associates WHERE user_id = auth.uid()));

drop policy if exists "admin_resources_all" on crm.associate_resources;
CREATE POLICY "admin_resources_all" ON crm.associate_resources FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());
drop policy if exists "associate_read_resources" on crm.associate_resources;
CREATE POLICY "associate_read_resources" ON crm.associate_resources FOR SELECT
  USING (is_active = true AND EXISTS (SELECT 1 FROM crm.associates WHERE user_id = auth.uid()));

drop policy if exists "associate_tickets_all" on crm.associate_support_tickets;
CREATE POLICY "associate_tickets_all" ON crm.associate_support_tickets FOR ALL
  USING (associate_id IN (SELECT id FROM crm.associates WHERE user_id = auth.uid()))
  WITH CHECK (associate_id IN (SELECT id FROM crm.associates WHERE user_id = auth.uid()));
drop policy if exists "admin_tickets_all" on crm.associate_support_tickets;
CREATE POLICY "admin_tickets_all" ON crm.associate_support_tickets FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());

-- Link leads/students to the associate who referred them
ALTER TABLE crm.leads
  ADD COLUMN IF NOT EXISTS referred_by_associate uuid REFERENCES crm.associates(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS crm_leads_referred_assoc_idx ON crm.leads(referred_by_associate);

ALTER TABLE crm.students
  ADD COLUMN IF NOT EXISTS referred_by_associate uuid REFERENCES crm.associates(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS crm_students_referred_assoc_idx ON crm.students(referred_by_associate) WHERE referred_by_associate IS NOT NULL;

-- ------------------------------------------------------------------------
-- 0017_dispatches_uploads.sql
-- ------------------------------------------------------------------------

-- Student document dispatch tracking
CREATE TABLE IF NOT EXISTS crm.student_dispatches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_name text NOT NULL,
  enrollment_number text,
  associate_id uuid REFERENCES crm.associates(id) ON DELETE SET NULL,
  document_type text NOT NULL DEFAULT 'marksheet',
  dispatch_type text NOT NULL DEFAULT 'outbound'
    CHECK (dispatch_type IN ('inbound', 'outbound')),
  courier text,
  tracking_number text,
  dispatch_date date,
  expected_delivery date,
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','dispatched','in_transit','delivered','returned','failed')),
  remarks text,
  student_phone text,
  father_name text,
  dispatched_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS crm_dispatches_assoc_idx ON crm.student_dispatches(associate_id);
CREATE INDEX IF NOT EXISTS crm_dispatches_status_idx ON crm.student_dispatches(status);
CREATE INDEX IF NOT EXISTS crm_dispatches_created_idx ON crm.student_dispatches(created_at DESC);
CREATE INDEX IF NOT EXISTS crm_dispatches_type_idx ON crm.student_dispatches(dispatch_type);

ALTER TABLE crm.student_dispatches ENABLE ROW LEVEL SECURITY;

drop policy if exists "admin_full_dispatch" on crm.student_dispatches;
CREATE POLICY "admin_full_dispatch" ON crm.student_dispatches FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());

-- Student-uploaded documents
CREATE TABLE IF NOT EXISTS crm.student_uploads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id uuid NOT NULL REFERENCES crm.students(id) ON DELETE CASCADE,
  document_type text NOT NULL,
  file_url text NOT NULL,
  remarks text,
  uploaded_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS crm_student_uploads_student_idx ON crm.student_uploads(student_id, uploaded_at DESC);

ALTER TABLE crm.student_uploads ENABLE ROW LEVEL SECURITY;

drop policy if exists "admin_student_uploads" on crm.student_uploads;
CREATE POLICY "admin_student_uploads" ON crm.student_uploads FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());

drop policy if exists "student_own_uploads_select" on crm.student_uploads;
CREATE POLICY "student_own_uploads_select" ON crm.student_uploads FOR SELECT
  USING (student_id IN (SELECT id FROM crm.students WHERE portal_user_id = auth.uid()));

drop policy if exists "student_own_uploads_insert" on crm.student_uploads;
CREATE POLICY "student_own_uploads_insert" ON crm.student_uploads FOR INSERT
  WITH CHECK (student_id IN (SELECT id FROM crm.students WHERE portal_user_id = auth.uid()));

-- ------------------------------------------------------------------------
-- 0018_payroll.sql
-- ------------------------------------------------------------------------

-- Payroll table

create table if not exists crm.payroll (
  id uuid primary key default gen_random_uuid(),
  -- FK added in 0019, once crm.employees exists.
  employee_id uuid not null,
  month integer not null check (month between 1 and 12),
  year integer not null,
  basic numeric(12,2) not null default 0,
  hra numeric(12,2) not null default 0,
  allowances numeric(12,2) not null default 0,
  incentive numeric(12,2) not null default 0,
  gross numeric(12,2) not null default 0,
  pf numeric(12,2) not null default 0,
  tds numeric(12,2) not null default 0,
  other_deductions numeric(12,2) not null default 0,
  advance_deduction numeric(10,2) not null default 0,
  net numeric(12,2) not null default 0,
  status text not null default 'draft' check (status in ('draft','processed','paid')),
  payment_date date,
  created_at timestamptz not null default now(),
  unique (employee_id, month, year)
);

create index if not exists payroll_emp_idx on crm.payroll(employee_id);
create index if not exists payroll_status_idx on crm.payroll(status);

alter table crm.payroll enable row level security;

drop policy if exists "admin_manage_payroll" on crm.payroll;
create policy "admin_manage_payroll" on crm.payroll for all
  using (crm.is_manager())
  with check (crm.is_manager());

