-- 0021_student_mentorships.sql
-- ------------------------------------------------------------------------

-- Student mentorship: admin assigns telecallers to students for follow-up work

CREATE TABLE IF NOT EXISTS crm.student_mentorships (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id    UUID NOT NULL REFERENCES crm.students(id) ON DELETE CASCADE,
  telecaller_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  task_type     TEXT NOT NULL CHECK (task_type IN ('work_assignment', 'practical', 'exam')),
  description   TEXT,
  rating        NUMERIC(3,1) CHECK (rating >= 0 AND rating <= 10),

  -- Admin approval fields
  status           TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'rejected')),
  salary_percentage NUMERIC(5,2),
  admin_remarks    TEXT,
  approved_by      UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  approved_at      TIMESTAMPTZ,

  created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_sm_student    ON crm.student_mentorships(student_id);
CREATE INDEX IF NOT EXISTS idx_sm_telecaller ON crm.student_mentorships(telecaller_id);
CREATE INDEX IF NOT EXISTS idx_sm_status     ON crm.student_mentorships(status);

ALTER TABLE crm.student_mentorships ENABLE ROW LEVEL SECURITY;

-- Admin/backend: full access
drop policy if exists "admin_mentorships_all" on crm.student_mentorships;
CREATE POLICY "admin_mentorships_all" ON crm.student_mentorships FOR ALL
  USING (crm.is_manager());

-- Telecallers: can read mentorships assigned to them
drop policy if exists "telecaller_view_own" on crm.student_mentorships;
CREATE POLICY "telecaller_view_own" ON crm.student_mentorships FOR SELECT
  USING (telecaller_id = auth.uid());

-- ------------------------------------------------------------------------
-- 0022_revenue_targets.sql
-- ------------------------------------------------------------------------

-- Revenue targets: assign monetary/lead targets to counsellors with bonus config

CREATE TABLE IF NOT EXISTS crm.revenue_targets (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  assignee_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  title TEXT NOT NULL DEFAULT 'Revenue Target',
  target_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (target_amount >= 0),
  lead_target INTEGER NOT NULL DEFAULT 0 CHECK (lead_target >= 0),
  conversion_target INTEGER NOT NULL DEFAULT 0 CHECK (conversion_target >= 0),
  period_type TEXT NOT NULL DEFAULT 'monthly' CHECK (period_type IN ('daily','weekly','monthly','quarterly','custom')),
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  bonus_percentage NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (bonus_percentage >= 0),
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived')),
  created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT revenue_targets_valid_dates CHECK (end_date >= start_date)
);

CREATE INDEX IF NOT EXISTS idx_rev_targets_assignee ON crm.revenue_targets(assignee_id);
CREATE INDEX IF NOT EXISTS idx_rev_targets_dates ON crm.revenue_targets(start_date, end_date);
CREATE INDEX IF NOT EXISTS idx_rev_targets_status ON crm.revenue_targets(status);

CREATE OR REPLACE FUNCTION crm.set_revenue_targets_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS revenue_targets_updated_at ON crm.revenue_targets;
CREATE TRIGGER revenue_targets_updated_at
  BEFORE UPDATE ON crm.revenue_targets
  FOR EACH ROW EXECUTE FUNCTION crm.set_revenue_targets_updated_at();

ALTER TABLE crm.revenue_targets ENABLE ROW LEVEL SECURITY;

drop policy if exists "admin_manage_revenue_targets" on crm.revenue_targets;
CREATE POLICY "admin_manage_revenue_targets"
  ON crm.revenue_targets FOR ALL
  USING (crm.is_manager())
  WITH CHECK (crm.is_manager());

drop policy if exists "counsellor_view_own_targets" on crm.revenue_targets;
CREATE POLICY "counsellor_view_own_targets"
  ON crm.revenue_targets FOR SELECT
  USING (assignee_id = auth.uid());

-- ------------------------------------------------------------------------
-- 0023_crm_grants.sql
-- ------------------------------------------------------------------------

-- PostgREST talks to these tables as `authenticated`, and a table with RLS on
-- but no GRANT denies every request before a policy is even consulted. 0008
-- granted its own thirteen tables; everything added in 0011–0022 needs the
-- same, or every new CRM screen returns an empty list with no error.
do $$
declare t text;
begin
  foreach t in array array[
    'student_documents','student_exams','appointments','lead_capture_forms',
    'notifications','notification_reads','student_notifications',
    'student_announcements','student_support_tickets','study_materials',
    'student_faqs','associates','associate_wallet_txns',
    'associate_notifications','associate_dispatches','wallet_recharge_requests',
    'associate_resources','associate_support_tickets','student_dispatches',
    'student_uploads','payroll','employees','attendance','leave_requests',
    'expenses','advance_salaries','department_litigations',
    'student_mentorships','revenue_targets'
  ] loop
    execute format('grant select, insert, update, delete on crm.%I to authenticated', t);
  end loop;
end $$;

grant usage, select on all sequences in schema crm to authenticated;

-- The public lead-capture page renders before login, so anon needs read on it.
-- Its policy already narrows that to `is_active = true`.
grant select on crm.lead_capture_forms to anon;

-- ------------------------------------------------------------------------
-- 0024_crm_service_role_grants.sql
-- ------------------------------------------------------------------------

-- Table grants for `service_role` in the crm schema.
--
-- In `public`, Supabase's bootstrap sets default privileges so service_role
-- gets every table automatically. A schema created by a migration inherits
-- none of that: 0008 granted `usage on schema crm` to service_role but never
-- any table, so every service-role request returned
--   42501  permission denied for table <t>
-- with RLS never even consulted. Caught against the live project the first
-- time the crm schema was exposed to the API.
--
-- The one caller this breaks is the bulk lead importer, which uses the service
-- role for its batch insert (`import-actions.ts`) — it would have failed on
-- the very first real import.

grant usage on schema crm to service_role;

grant select, insert, update, delete
  on all tables in schema crm to service_role;

grant usage, select on all sequences in schema crm to service_role;

-- `all tables in schema` only covers what exists right now. Default privileges
-- cover whatever a later migration adds, so this bug cannot come back.
alter default privileges in schema crm
  grant select, insert, update, delete on tables to service_role;

alter default privileges in schema crm
  grant usage, select on sequences to service_role;

-- Same reasoning for `authenticated`: 0008 and 0023 each had to list their own
-- tables by hand, and 0023 exists only because 0011-0022 were forgotten once.
alter default privileges in schema crm
  grant select, insert, update, delete on tables to authenticated;

alter default privileges in schema crm
  grant usage, select on sequences to authenticated;
